import React, { createContext, useContext, useEffect, useMemo, useState } from 'react';
import { loginApi, signupApi, meApi, logoutApi } from './api';

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  // Try to fetch current session from backend on mount
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const res = await meApi();
        if (!cancelled) setUser(res.user);
      } catch (e) {
        // Fallback to localStorage if present (from a previous session before backend wiring)
        const raw = localStorage.getItem('auth:user');
        if (raw && !cancelled) {
          try { setUser(JSON.parse(raw)); } catch {}
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => { cancelled = true; };
  }, []);

  // Keep a lightweight fallback cache so UI can restore quickly even before /me returns
  useEffect(() => {
    if (user) localStorage.setItem('auth:user', JSON.stringify(user));
    else localStorage.removeItem('auth:user');
  }, [user]);

  const login = async ({ email, password }) => {
    const res = await loginApi({ email, password });
    setUser(res.user);
  };

  const signup = async ({ fullName, email, password }) => {
    const res = await signupApi({ fullName, email, password });
    setUser(res.user);
  };

  const loginWithGoogle = async () => {
    // Placeholder: in future, redirect to Google OAuth
    throw new Error('Google login not yet configured');
  };

  const logout = async () => {
    try { await logoutApi(); } catch {}
    setUser(null);
  };

  const value = useMemo(() => ({ user, loading, login, signup, loginWithGoogle, logout }), [user, loading]);

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
}
